//! `orb emit <target> <file>` — dump per-schema generated code for inspection.
//!
//! Three targets:
//!
//! - `orb` — lower a `.lolo` file to canonical `.orb` JSON.
//! - `ts`  — run the TypeScript backend and stream the resulting code.
//! - `py`  — run the Python backend and stream the resulting code.
//!
//! Bypasses the Shell template copy and the filesystem write step that
//! `generate_from_file` normally performs. Calls `Backend::generate(&OirModule)`
//! directly and sinks the returned `GeneratedOutput` to stdout or a file.
//!
//! See `docs/Almadar_Compiler_Emit_Code.md` (Phases 1–2) for the design.

use anyhow::{anyhow, Result};
use clap::ValueEnum;
use std::io::Read;
use std::path::{Path, PathBuf};

use orbital_compiler::generate::{Backend, GeneratedFile, GeneratedOutput};
use orbital_compiler::phases::{compile_schema, CompilerOptions};

pub mod sourcemap;
pub mod spans;
pub mod trace;

// --- Enums wired into clap --------------------------------------------------

/// Output target for `orb emit`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum EmitTarget {
    /// Canonical `.orb` JSON (accepts `.lolo` or `.orb` input).
    Orb,
    /// TypeScript source (generated by `orbital-shell-typescript`).
    Ts,
    /// Python source (generated by `orbital-shell-python`).
    Py,
    /// `.lolo` source printed from the lowered IR (accepts `.orb` or `.lolo` input).
    Lolo,
}

/// How to render the filtered files to the sink.
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum, Default)]
pub enum EmitFormat {
    /// Human-readable stream: each file preceded by a `// ───── path ─────` banner.
    #[default]
    Stream,
    /// Markdown fenced code blocks, one per file, language-tagged.
    Markdown,
    /// JSON object keyed by file path (machine-consumable).
    Json,
    /// Concatenated source only — no banners, no separators.
    Raw,
}

/// Server framework choice — used only when `target = Ts`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum, Default)]
pub enum EmitServer {
    /// Hono (default — matches `orb compile`).
    #[default]
    Hono,
    Express,
}

// --- Entry point called from main.rs ---------------------------------------

/// Options for a single `orb emit` invocation.
pub struct EmitOptions {
    pub target: EmitTarget,
    pub path: Option<PathBuf>,
    pub section: Option<String>,
    pub output: Option<PathBuf>,
    pub format: Option<EmitFormat>,
    pub only: Option<String>,
    pub server: EmitServer,
    /// When true, write a Source Map v3 sidecar at `<output>.map` (or,
    /// when emitting to stdout, append a `//# sourceMappingURL=…` comment
    /// with an inline base64-encoded map). Ignored for `target = orb` and
    /// for `format = json | raw`.
    pub map: bool,
}

/// Run the emit pipeline end-to-end.
pub fn run(opts: EmitOptions) -> Result<()> {
    let source = read_input(opts.path.as_deref())?;
    let source_path = opts
        .path
        .as_deref()
        .map(|p| p.display().to_string())
        .unwrap_or_else(|| "<stdin>".to_string());

    match opts.target {
        EmitTarget::Orb => emit_orb(&source, opts.output.as_deref(), &source_path),
        EmitTarget::Lolo => emit_lolo(&source, opts.output.as_deref(), &source_path),
        EmitTarget::Ts | EmitTarget::Py => emit_code(opts, &source, &source_path),
    }
}

fn read_input(path: Option<&Path>) -> Result<String> {
    match path {
        Some(p) => {
            std::fs::read_to_string(p).map_err(|e| anyhow!("Failed to read {}: {}", p.display(), e))
        }
        None => {
            let mut buf = String::new();
            std::io::stdin()
                .read_to_string(&mut buf)
                .map_err(|e| anyhow!("Failed to read stdin: {}", e))?;
            Ok(buf)
        }
    }
}

fn write_output(rendered: &str, output: Option<&Path>) -> Result<()> {
    match output {
        Some(p) => std::fs::write(p, rendered)
            .map_err(|e| anyhow!("Failed to write {}: {}", p.display(), e)),
        None => {
            // Trailing newline on pure-stdout output for nicer shell concat.
            print!("{}", rendered);
            if !rendered.ends_with('\n') {
                println!();
            }
            Ok(())
        }
    }
}

// --- Target: orb -----------------------------------------------------------

fn emit_orb(source: &str, output: Option<&Path>, source_path: &str) -> Result<()> {
    // Parse whichever surface the file uses (same dispatch as
    // `utils::detect::parse_schema_auto_typed`, plus the prior-ledger anchor).
    //
    // Id stability: when emitting in place (the registry regen pattern —
    // `orb emit orb <lolo> --output <existing.orb>`), the existing output is
    // the prior ledger anchor, so re-emits reuse ids instead of minting fresh
    // ones every run.
    let prior = output
        .filter(|p| p.exists())
        .and_then(|p| std::fs::read_to_string(p).ok())
        .and_then(|s| {
            orbital_core::schema::parse_schema(&crate::utils::translate_schema_content(&s)).ok()
        });
    let schema = parse_any_syntax_with_prior(source, prior.as_ref(), source_path)?;
    let value =
        serde_json::to_value(&schema).map_err(|e| anyhow!("Failed to serialize schema: {}", e))?;
    let cleaned = crate::strip_json_nulls(value);
    let json = serde_json::to_string_pretty(&orbital_core::util::canonical_json(&cleaned))
        .map_err(|e| anyhow!("Failed to serialize schema: {}", e))?;
    write_output(&json, output)?;
    // A program with locales ships its merged catalogs beside the emitted `.orb`
    // (`<stem>.<locale>.json`, the same files `orb resolve --output` writes).
    match output {
        Some(out) if schema.locales.as_ref().is_some_and(|l| !l.is_empty()) => {
            let path = Path::new(source_path);
            let options = orbital_compiler::CompilerOptions::from_env();
            let (resolved, _lazy) =
                orbital_compiler::phases::lazy::resolve_program_with_path(schema, &options, Some(path))
                    .map_err(|e| anyhow!("Failed to resolve {} for its catalogs: {}", source_path, e))?;
            let program_dir = path.parent().unwrap_or(Path::new("."));
            orbital_compiler::phases::messages::write_catalogs(out, &resolved, program_dir)
                .map_err(|e| anyhow!("Failed to write catalogs beside {}: {}", out.display(), e))?;
            // Its own per-behavior catalogs travel with it: a program importing it
            // from the output folder reads `<folder>/locales/<locale>/<name>.json`.
            let out_dir = out.parent().unwrap_or(Path::new("."));
            for locale in resolved.locales.iter().flatten() {
                let file = Path::new("locales").join(locale).join(format!("{}.json", resolved.name));
                let (from, to) = (program_dir.join(&file), out_dir.join(&file));
                if from.exists() && from.canonicalize().ok() != to.canonicalize().ok() {
                    std::fs::create_dir_all(to.parent().unwrap_or(out_dir))?;
                    std::fs::copy(&from, &to)
                        .map_err(|e| anyhow!("Failed to copy {} to {}: {}", from.display(), to.display(), e))?;
                }
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

// --- Target: lolo ----------------------------------------------------------

fn emit_lolo(source: &str, output: Option<&Path>, source_path: &str) -> Result<()> {
    let schema = parse_any_syntax(source, source_path)?;
    let lolo = orbital_lolo::schema_to_lolo(&schema)
        .map_err(|e| anyhow!("{}: {}", source_path, e))?;
    write_output(&lolo, output)
}

/// Parse either `.lolo` surface syntax or `.orb` JSON based on first
/// non-whitespace character. Shared helper; mirrors main.rs's dispatch.
fn parse_any_syntax(
    source: &str,
    source_path: &str,
) -> Result<orbital_core::schema::OrbitalSchema> {
    parse_any_syntax_with_prior(source, None, source_path)
}

/// [`parse_any_syntax`] with a prior schema anchoring id reuse on the `.lolo`
/// branch (`.orb` JSON input passes through untouched — its ids ARE the ids).
fn parse_any_syntax_with_prior(
    source: &str,
    prior: Option<&orbital_core::schema::OrbitalSchema>,
    source_path: &str,
) -> Result<orbital_core::schema::OrbitalSchema> {
    let first = source
        .trim_start_matches('\u{FEFF}')
        .trim_start()
        .chars()
        .next();
    if matches!(first, Some('{')) {
        // `.orb` JSON — native-language keys are translated first, as every other command does.
        let translated = crate::utils::translate_schema_content(source);
        orbital_core::schema::parse_schema(&translated)
            .map_err(|e| anyhow!("JSON parse error: {}", e))
    } else {
        // Assume `.lolo` surface syntax.
        orbital_lolo::parse_and_lower_str_with_prior_at(source, prior, source_path)
            .map_err(|e| anyhow!("LOLO parse error: {}", e.render_with_hint()))
    }
}

// --- Target: ts | py -------------------------------------------------------

fn emit_code(opts: EmitOptions, source: &str, source_path: &str) -> Result<()> {
    let schema = parse_any_syntax(source, source_path)?;
    let mut compiler_options = CompilerOptions::from_env();
    compiler_options.service_runtimes = Some(crate::utils::load_services_registry(None).runtimes);
    let unresolved = schema.clone();
    let module = compile_schema(schema, &compiler_options)
        .map_err(|e| anyhow!("Schema compilation failed: {}", e))?;

    let output: GeneratedOutput = match opts.target {
        EmitTarget::Ts => {
            use orbital_shell_typescript::{ServerFramework, TypeScriptBackend};
            let backend = TypeScriptBackend {
                server_framework: match opts.server {
                    EmitServer::Hono => ServerFramework::Hono,
                    EmitServer::Express => ServerFramework::Express,
                },
                browser_schema: if module.entities.iter().any(|e| e.local) || !module.browser_services.is_empty() {
                    Some(
                        orbital_verify::resolve_schema_with_source(unresolved, Some(Path::new(source_path)))
                            .map_err(|e| anyhow!("Failed to resolve schema for the browser store: {}", e))?,
                    )
                } else {
                    None
                },
                ..TypeScriptBackend::default()
            };
            backend.generate(&module)
        }
        EmitTarget::Py => {
            use orbital_shell_python::PythonBackend;
            let backend = PythonBackend::new();
            backend.generate(&module)
        }
        EmitTarget::Orb | EmitTarget::Lolo => {
            unreachable!("orb and lolo targets are routed before code generation")
        }
    };

    let selector = opts
        .section
        .as_deref()
        .map(selector::parse)
        .transpose()?
        .unwrap_or(selector::Section::All);

    let only = opts.only.as_deref().map(filter::parse_only).transpose()?;

    let files = filter::apply(&output.files, &selector, only.as_ref(), opts.target);

    if files.is_empty() {
        eprintln!(
            "warning: selector {} matched zero generated files",
            opts.section.as_deref().unwrap_or("(default)")
        );
    }

    let format = opts
        .format
        .unwrap_or_else(|| auto_format(opts.output.as_deref()));
    let rendered = render::render(&files, format, opts.target);

    // Source-map emission. Only applies when the user asked for `--map`
    // and the render format produces source code (not the JSON object view).
    if opts.map
        && matches!(
            format,
            EmitFormat::Stream | EmitFormat::Markdown | EmitFormat::Raw
        )
    {
        emit_maps(&opts, source, &files, &rendered)?;
    }

    write_output(&rendered, opts.output.as_deref())
}

/// Populate sidecar source maps for each generated file (when written to
/// disk) or append a single inline map covering the entire rendered stream
/// (when written to stdout).
fn emit_maps(
    opts: &EmitOptions,
    orb_source: &str,
    files: &[&GeneratedFile],
    rendered: &str,
) -> Result<()> {
    let spans = spans::scan(orb_source);
    let orb_path = opts
        .path
        .clone()
        .unwrap_or_else(|| PathBuf::from("<stdin>.orb"));

    match opts.output.as_deref() {
        Some(out) => {
            // Sidecar: write one `<out>.ts.map`-style file. File-level
            // granularity — maps every line of the concatenated stream to
            // the first tracked node we know about (good enough signal for
            // IDE navigation until Phase 5 per-line spans land).
            let first_anchor = files.iter().find_map(|f| {
                sourcemap::classify_file(f, opts.target)
                    .and_then(|(kind, name)| spans.lookup(kind, &name).map(|range| (name, range)))
            });
            let Some((_, range)) = first_anchor else {
                eprintln!("warning: --map: no tracked node found in selected files; map skipped");
                return Ok(());
            };
            let map_path = sourcemap::map_path_for_output(out);
            let map_json = sourcemap::build_map_for_file(rendered, orb_source, &orb_path, range);
            std::fs::write(&map_path, map_json)
                .map_err(|e| anyhow!("Failed to write {}: {}", map_path.display(), e))?;
            eprintln!("source map: {}", map_path.display());
        }
        None => {
            // Inline: append `//# sourceMappingURL=data:…` to stdout. Only
            // useful for TS output (Python tooling doesn't consume inline
            // source-map comments), and even then it's diagnostic-only.
            // For Python we skip silently.
            if matches!(opts.target, EmitTarget::Ts) {
                let first_anchor = files.iter().find_map(|f| {
                    sourcemap::classify_file(f, opts.target).and_then(|(kind, name)| {
                        spans.lookup(kind, &name).map(|range| (name, range))
                    })
                });
                if let Some((_, range)) = first_anchor {
                    let map_json =
                        sourcemap::build_map_for_file(rendered, orb_source, &orb_path, range);
                    let b64 = base64_encode(map_json.as_bytes());
                    println!("//# sourceMappingURL=data:application/json;base64,{}", b64);
                }
            }
        }
    }
    Ok(())
}

/// Base64 encoder sufficient for inline source-map comments. Avoids pulling
/// in `base64` as a crate dep — the map JSON is small and this is
/// non-hot-path.
fn base64_encode(bytes: &[u8]) -> String {
    const ALPHA: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity((bytes.len() + 2) / 3 * 4);
    let mut i = 0;
    while i + 3 <= bytes.len() {
        let b0 = bytes[i] as u32;
        let b1 = bytes[i + 1] as u32;
        let b2 = bytes[i + 2] as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(ALPHA[((n >> 18) & 63) as usize] as char);
        out.push(ALPHA[((n >> 12) & 63) as usize] as char);
        out.push(ALPHA[((n >> 6) & 63) as usize] as char);
        out.push(ALPHA[(n & 63) as usize] as char);
        i += 3;
    }
    let rem = bytes.len() - i;
    if rem == 1 {
        let n = (bytes[i] as u32) << 16;
        out.push(ALPHA[((n >> 18) & 63) as usize] as char);
        out.push(ALPHA[((n >> 12) & 63) as usize] as char);
        out.push('=');
        out.push('=');
    } else if rem == 2 {
        let n = ((bytes[i] as u32) << 16) | ((bytes[i + 1] as u32) << 8);
        out.push(ALPHA[((n >> 18) & 63) as usize] as char);
        out.push(ALPHA[((n >> 12) & 63) as usize] as char);
        out.push(ALPHA[((n >> 6) & 63) as usize] as char);
        out.push('=');
    }
    out
}

/// Pick a format from the output file extension if `--format` was not given.
/// `*.md` → Markdown, `*.json` → Json, anything else (or stdout) → Stream.
fn auto_format(output: Option<&Path>) -> EmitFormat {
    match output.and_then(|p| p.extension()).and_then(|e| e.to_str()) {
        Some("md") | Some("markdown") => EmitFormat::Markdown,
        Some("json") => EmitFormat::Json,
        _ => EmitFormat::Stream,
    }
}

// --- Selector parser -------------------------------------------------------

mod selector {
    use super::*;

    /// Parsed section selector. Anything this module can't express precisely
    /// falls back to `All` (keeps the first pass simple; the grammar in the
    /// design doc says bare `traits`/`entities`/`pages` mean "all of that kind").
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum Section {
        All,
        /// `entities` — every entity.
        AllEntities,
        /// `entities.Foo` — a specific entity by name.
        Entity(String),
        /// `traits` — every trait.
        AllTraits,
        /// `traits.Foo` (and any deeper path under it) — a specific trait.
        /// Deeper selectors still map to this for Phase 2; expression-level
        /// filtering is Phase 5.
        Trait(String),
        /// `pages` — every page.
        AllPages,
        /// `pages.NAME` — a specific page by folder name.
        Page(String),
        /// `services` — every service.
        AllServices,
        /// `services.NAME` — a specific service.
        Service(String),
    }

    pub fn parse(input: &str) -> Result<Section> {
        let input = input.trim();
        if input.is_empty() {
            return Ok(Section::All);
        }
        // Tokenize on `.` and strip optional `orbitals[i].` prefix.
        let mut segs: Vec<&str> = input.split('.').collect();
        if let Some(first) = segs.first() {
            // `orbitals[0].…` — ignore the indexing for Phase 2 (we treat all
            // orbitals as one flat namespace). If the user asked for a specific
            // orbital, that's Phase 5 work — here we just accept and descend.
            if first.starts_with("orbitals[") && first.ends_with(']') {
                segs.remove(0);
            }
        }

        let head = segs.first().copied().unwrap_or_default();
        let rest = segs.get(1).copied();

        Ok(match (head, rest) {
            ("entities", None) => Section::AllEntities,
            ("entities", Some(name)) if is_name(name) => Section::Entity(name.to_string()),
            ("traits", None) => Section::AllTraits,
            ("traits", Some(name)) if is_name(name) => Section::Trait(name.to_string()),
            ("pages", None) => Section::AllPages,
            ("pages", Some(name)) if is_name(name) => Section::Page(name.to_string()),
            ("services", None) => Section::AllServices,
            ("services", Some(name)) if is_name(name) => Section::Service(name.to_string()),
            // `entity` as a segment (used with orbitals[i].entity) means "the
            // entity of this orbital." With the orbitals[] prefix stripped we
            // treat it identically to `entities`.
            ("entity", None) => Section::AllEntities,
            _ => {
                return Err(anyhow!(
                    "unknown section selector {:?} — supported forms: \
                     entities[.NAME] | traits[.NAME] | pages[.NAME] | \
                     services[.NAME] | orbitals[i].<section>",
                    input
                ))
            }
        })
    }

    // Lexical predicates described in the design doc §Selector grammar.
    // Hand-written character checks — no `regex` crate dependency.

    pub(super) fn is_name(s: &str) -> bool {
        let mut cs = s.chars();
        matches!(cs.next(), Some(c) if c.is_ascii_alphabetic() || c == '_')
            && cs.all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
    }

    #[allow(dead_code)] // Reserved for orbitals[i] and transitions[i] parsing (Phase 5).
    pub(super) fn is_index(s: &str) -> bool {
        !s.is_empty() && s.chars().all(|c| c.is_ascii_digit())
    }

    #[allow(dead_code)] // Reserved for transitions.EVENT parsing (Phase 5).
    pub(super) fn is_event_key(s: &str) -> bool {
        let mut cs = s.chars();
        matches!(cs.next(), Some(c) if c.is_ascii_uppercase() || c == '_')
            && cs.all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_')
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn predicates() {
            assert!(is_name("Foo"));
            assert!(is_name("foo_bar-baz"));
            assert!(is_name("_private"));
            assert!(!is_name("2Bad"));
            assert!(!is_name(""));

            assert!(is_index("0"));
            assert!(is_index("42"));
            assert!(!is_index(""));
            assert!(!is_index("x1"));

            assert!(is_event_key("OPEN"));
            assert!(is_event_key("CLOSE_WITH_SAVE"));
            assert!(is_event_key("_PRIVATE"));
            assert!(!is_event_key("open"));
            assert!(!is_event_key("OpenBad"));
        }

        #[test]
        fn selector_parses() {
            assert_eq!(parse("").unwrap(), Section::All);
            assert_eq!(parse("entities").unwrap(), Section::AllEntities);
            assert_eq!(
                parse("entities.ModalRecord").unwrap(),
                Section::Entity("ModalRecord".into())
            );
            assert_eq!(parse("traits").unwrap(), Section::AllTraits);
            assert_eq!(
                parse("traits.ModalRecordModal").unwrap(),
                Section::Trait("ModalRecordModal".into())
            );
            assert_eq!(parse("pages").unwrap(), Section::AllPages);
            // orbitals[0].traits.Foo → descends past the orbitals prefix.
            assert_eq!(
                parse("orbitals[0].traits.Foo").unwrap(),
                Section::Trait("Foo".into())
            );
        }

        #[test]
        fn selector_rejects() {
            assert!(parse("xyz").is_err());
            assert!(parse("entities.2Bad").is_err());
        }
    }
}

// --- File filter -----------------------------------------------------------

mod filter {
    use super::selector::Section;
    use super::*;

    /// Coarse "--only" filter.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub enum OnlyKind {
        Entities,
        Traits,
        Pages,
        Hooks,
        Components,
        Routes,
        Services,
        Tests,
    }

    pub fn parse_only(input: &str) -> Result<Vec<OnlyKind>> {
        input
            .split(',')
            .map(|tok| {
                let t = tok.trim().to_ascii_lowercase();
                Ok(match t.as_str() {
                    "entities" | "entity" => OnlyKind::Entities,
                    "traits" | "trait" => OnlyKind::Traits,
                    "pages" | "page" => OnlyKind::Pages,
                    "hooks" | "hook" => OnlyKind::Hooks,
                    "components" | "component" => OnlyKind::Components,
                    "routes" | "route" => OnlyKind::Routes,
                    "services" | "service" => OnlyKind::Services,
                    "tests" | "test" => OnlyKind::Tests,
                    _ => {
                        return Err(anyhow!(
                            "unknown --only kind {:?} — supported: entities, traits, pages, hooks, components, routes, services, tests",
                            tok
                        ))
                    }
                })
            })
            .collect()
    }

    /// Apply the parsed selector + only filter + target to `files`, returning
    /// a new owned vec of references. Matching is path-substring based; a
    /// `content` fallback grep is used for selectors that don't map cleanly
    /// to file paths (e.g. entity names within a shared-entities file).
    pub fn apply<'a>(
        files: &'a [GeneratedFile],
        section: &Section,
        only: Option<&Vec<OnlyKind>>,
        target: EmitTarget,
    ) -> Vec<&'a GeneratedFile> {
        files
            .iter()
            .filter(|f| matches_section(f, section, target))
            .filter(|f| match only {
                None => true,
                Some(kinds) => kinds.iter().any(|k| matches_only(f, *k, target)),
            })
            .collect()
    }

    fn matches_section(file: &GeneratedFile, section: &Section, target: EmitTarget) -> bool {
        let path = file.path.as_str();
        let content = file.content.as_str();
        match (section, target) {
            (Section::All, _) => true,

            (Section::AllEntities, EmitTarget::Ts) => path.starts_with("packages/shared/"),
            (Section::AllEntities, EmitTarget::Py) => path.starts_with("entities/"),
            (Section::AllEntities, EmitTarget::Orb | EmitTarget::Lolo) => unreachable!(),

            (Section::Entity(name), EmitTarget::Ts) => {
                path.starts_with("packages/shared/")
                    && (path.contains(name)
                        || content.contains(&format!("interface {} ", name))
                        || content.contains(&format!("interface {}{{", name)))
            }
            (Section::Entity(name), EmitTarget::Py) => {
                path.starts_with("entities/")
                    && (path.contains(name) || content.contains(&format!("class {}", name)))
            }
            (Section::Entity(_), EmitTarget::Orb | EmitTarget::Lolo) => unreachable!(),

            (Section::AllTraits, EmitTarget::Ts) => {
                path.contains("/traits/") || path.starts_with("packages/server/src/routes/")
            }
            (Section::AllTraits, EmitTarget::Py) => {
                path.starts_with("traits/") || path.starts_with("routes/")
            }
            (Section::AllTraits, EmitTarget::Orb | EmitTarget::Lolo) => unreachable!(),

            (Section::Trait(name), EmitTarget::Ts) => {
                let hooks_dir = format!("/traits/use{}", name);
                let components_dir = format!("/traits/{}", name);
                let route_file = format!("/routes/{}", to_kebab(name));
                path.contains(&hooks_dir)
                    || path.contains(&components_dir)
                    || path.contains(&route_file)
            }
            (Section::Trait(name), EmitTarget::Py) => {
                let snake = to_snake(name);
                path == format!("traits/{}.py", snake) || path == format!("routes/{}.py", snake)
            }
            (Section::Trait(_), EmitTarget::Orb | EmitTarget::Lolo) => unreachable!(),

            (Section::AllPages, EmitTarget::Ts) => {
                path.starts_with("packages/client/src/features/")
            }
            (Section::AllPages, EmitTarget::Py) => {
                // Python backend doesn't currently emit per-page files.
                false
            }
            (Section::AllPages, EmitTarget::Orb | EmitTarget::Lolo) => unreachable!(),

            (Section::Page(name), EmitTarget::Ts) => {
                path.starts_with(&format!("packages/client/src/features/{}", name))
            }
            (Section::Page(_), EmitTarget::Py) => false,
            (Section::Page(_), EmitTarget::Orb | EmitTarget::Lolo) => unreachable!(),

            (Section::AllServices, EmitTarget::Ts) => path.contains("/services/"),
            (Section::AllServices, EmitTarget::Py) => {
                path.starts_with("services/") || path.contains("service")
            }
            (Section::AllServices, EmitTarget::Orb | EmitTarget::Lolo) => unreachable!(),

            (Section::Service(name), EmitTarget::Ts) => {
                path.contains("/services/") && path.contains(name)
            }
            (Section::Service(name), EmitTarget::Py) => {
                path.contains("service") && (path.contains(name) || content.contains(name))
            }
            (Section::Service(_), EmitTarget::Orb | EmitTarget::Lolo) => unreachable!(),
        }
    }

    fn matches_only(file: &GeneratedFile, kind: OnlyKind, target: EmitTarget) -> bool {
        let p = file.path.as_str();
        match (kind, target) {
            (OnlyKind::Entities, EmitTarget::Ts) => p.starts_with("packages/shared/"),
            (OnlyKind::Entities, EmitTarget::Py) => p.starts_with("entities/"),
            (OnlyKind::Traits, EmitTarget::Ts) => {
                p.contains("/traits/") || p.starts_with("packages/server/src/routes/")
            }
            (OnlyKind::Traits, EmitTarget::Py) => {
                p.starts_with("traits/") || p.starts_with("routes/")
            }
            (OnlyKind::Pages, EmitTarget::Ts) => p.starts_with("packages/client/src/features/"),
            (OnlyKind::Pages, EmitTarget::Py) => false,
            (OnlyKind::Hooks, EmitTarget::Ts) => p.contains("/hooks/"),
            (OnlyKind::Hooks, EmitTarget::Py) => false,
            (OnlyKind::Components, EmitTarget::Ts) => p.contains("/components/"),
            (OnlyKind::Components, EmitTarget::Py) => false,
            (OnlyKind::Routes, EmitTarget::Ts) => p.starts_with("packages/server/src/routes/"),
            (OnlyKind::Routes, EmitTarget::Py) => p.starts_with("routes/"),
            (OnlyKind::Services, _) => p.contains("services") || p.contains("service"),
            (OnlyKind::Tests, EmitTarget::Ts) => {
                p.contains("__tests__") || p.ends_with(".test.tsx") || p.ends_with(".test.ts")
            }
            (OnlyKind::Tests, EmitTarget::Py) => p.starts_with("tests/") || p.starts_with("test_"),
            (_, EmitTarget::Orb | EmitTarget::Lolo) => unreachable!(),
        }
    }

    // Canonical `str_utils` impls (Pillar F3). `to_kebab` is the NAIVE,
    // non-acronym-aware variant (`to_kebab_case_simple`) — trait names here are
    // simple PascalCase, so it matches the acronym-aware form anyway.
    fn to_kebab(name: &str) -> String {
        orbital_core::str_utils::to_kebab_case_simple(name)
    }

    fn to_snake(name: &str) -> String {
        orbital_core::str_utils::to_snake_case(name)
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn kebab_snake() {
            assert_eq!(to_kebab("ModalRecordModal"), "modal-record-modal");
            assert_eq!(to_snake("ModalRecordModal"), "modal_record_modal");
        }

        #[test]
        fn only_parse() {
            let kinds = parse_only("entities,traits,tests").unwrap();
            assert_eq!(
                kinds,
                vec![OnlyKind::Entities, OnlyKind::Traits, OnlyKind::Tests]
            );
            assert!(parse_only("garbage").is_err());
        }
    }
}

// --- Rendering -------------------------------------------------------------

mod render {
    use super::*;

    pub fn render(files: &[&GeneratedFile], format: EmitFormat, target: EmitTarget) -> String {
        match format {
            EmitFormat::Stream => render_stream(files),
            EmitFormat::Markdown => render_markdown(files, target),
            EmitFormat::Json => render_json(files),
            EmitFormat::Raw => render_raw(files),
        }
    }

    fn render_stream(files: &[&GeneratedFile]) -> String {
        let mut out = String::new();
        for (i, f) in files.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            out.push_str(&format!("// ───── {} ─────\n", f.path));
            out.push_str(&f.content);
            if !f.content.ends_with('\n') {
                out.push('\n');
            }
        }
        out
    }

    fn render_markdown(files: &[&GeneratedFile], target: EmitTarget) -> String {
        let lang = match target {
            EmitTarget::Ts => "typescript",
            EmitTarget::Py => "python",
            EmitTarget::Orb | EmitTarget::Lolo => "json",
        };
        let mut out = String::new();
        for f in files {
            out.push_str(&format!("### `{}`\n\n```{}\n", f.path, lang));
            out.push_str(&f.content);
            if !f.content.ends_with('\n') {
                out.push('\n');
            }
            out.push_str("```\n\n");
        }
        out
    }

    fn render_json(files: &[&GeneratedFile]) -> String {
        let map: serde_json::Map<String, serde_json::Value> = files
            .iter()
            .map(|f| (f.path.clone(), serde_json::Value::String(f.content.clone())))
            .collect();
        serde_json::to_string_pretty(&serde_json::Value::Object(map)).unwrap_or_default()
    }

    fn render_raw(files: &[&GeneratedFile]) -> String {
        let mut out = String::new();
        for f in files {
            out.push_str(&f.content);
            if !f.content.ends_with('\n') {
                out.push('\n');
            }
        }
        out
    }
}
